{
  "first": {
    "company": "Novo Nordisk",
    "mechanism": "三座廠在簽約前已替公司生產。取得廠房所有權本身不會增加充填量，管理層預期新增產能自 2026 年起才逐步釋出。",
    "catalyst": "截至 2025 年 6 月 30 日，公司更新三座廠的投產時程或產品供應指引。",
    "prediction": "研究期內，公司對三座廠的展望仍將新增充填產能列為 2026 年起的貢獻，2025 年上半年的供應指引不會因這筆收購帶來的新增產能而上修。",
    "invalidation": "若公司在研究期內明確表示收購已使三座廠的可用充填產能高於原合作安排，並據此上修 2025 年上半年的供應指引，則假說失效。",
    "materiality": "估算 2025 年上半年營收時，應將三座廠原已承接的產量計入基準，避免把同一批產量再次列為收購帶來的銷量成長。",
    "evidence_ids": ["novo-sites:capacity"]
  },
  "second": {
    "company": "Novo Nordisk",
    "mechanism": "約 110 億美元的預付款使收購對現金的影響集中於付款時點。購廠安排與 Novo Holdings 收購 Catalent 的交易相關，因此兩筆交易的進度會影響資金需求何時顯現。",
    "catalyst": "截至 2025 年 6 月 30 日，Novo Holdings 收購 Catalent 的進度，以及 Novo Nordisk 對購廠交割與付款的披露。",
    "prediction": "若購廠交易在研究期內按公告條款交割，預期 Novo Nordisk 會在交割時支付約 110 億美元，收購現金支出將早於管理層預期自 2026 年起出現的新增產能。",
    "invalidation": "若交易在研究期內交割，但披露顯示交割時的現金支付額顯著低於約 110 億美元，例如大部分對價改為遞延支付，則假說失效。若期末仍未交割，付款預測尚待驗證。",
    "materiality": "約 110 億美元的付款時點會影響期末流動性估算。研究期內的資金需求取決於交割進度，新增產能的預期貢獻則落在研究期之後。",
    "evidence_ids": ["novo-sites:acquisition", "novo-sites:capacity"]
  }
}
